changeSet.sql:
DROP POLICY IF EXISTS chunks_gate_probe_owner_read ON nexus.chunks; CREATE POLICY chunks_gate_probe_owner_read ON nexus.chunks FOR SELECT TO CURRENT_USER USING (true);
CREATE OR REPLACE FUNCTION nexus.text_gate_probe_384( p_text text, p_collections text[], p_where jsonb, p_where_path text, p_cap int ) RETURNS SETOF bytea LANGUAGE sql STABLE SECURITY DEFINER SET search_path = pg_catalog, pg_temp AS $$ SELECT c.chash FROM nexus.chunks c WHERE c.tenant_id = NULLIF(pg_catalog.current_setting('nexus.tenant', true), '') AND c.collection = ANY(p_collections) AND EXISTS (SELECT 1 FROM nexus.chunk_live_owners(c.tenant_id, c.collection, c.chash)) AND (p_where IS NULL OR c.metadata @> p_where) AND (p_where_path IS NULL OR c.metadata @@ p_where_path::jsonpath) AND (c.chunk_tsv @@ pg_catalog.plainto_tsquery('english', p_text) OR p_text OPERATOR(nexus.<%) c.chunk_text) LIMIT p_cap $$;
CREATE OR REPLACE FUNCTION nexus.text_gate_probe_768( p_text text, p_collections text[], p_where jsonb, p_where_path text, p_cap int ) RETURNS SETOF bytea LANGUAGE sql STABLE SECURITY DEFINER SET search_path = pg_catalog, pg_temp AS $$ SELECT c.chash FROM nexus.chunks c WHERE c.tenant_id = NULLIF(pg_catalog.current_setting('nexus.tenant', true), '') AND c.collection = ANY(p_collections) AND EXISTS (SELECT 1 FROM nexus.chunk_live_owners(c.tenant_id, c.collection, c.chash)) AND (p_where IS NULL OR c.metadata @> p_where) AND (p_where_path IS NULL OR c.metadata @@ p_where_path::jsonpath) AND (c.chunk_tsv @@ pg_catalog.plainto_tsquery('english', p_text) OR p_text OPERATOR(nexus.<%) c.chunk_text) LIMIT p_cap $$;
CREATE OR REPLACE FUNCTION nexus.text_gate_probe_1024( p_text text, p_collections text[], p_where jsonb, p_where_path text, p_cap int ) RETURNS SETOF bytea LANGUAGE sql STABLE SECURITY DEFINER SET search_path = pg_catalog, pg_temp AS $$ SELECT c.chash FROM nexus.chunks c WHERE c.tenant_id = NULLIF(pg_catalog.current_setting('nexus.tenant', true), '') AND c.collection = ANY(p_collections) AND EXISTS (SELECT 1 FROM nexus.chunk_live_owners(c.tenant_id, c.collection, c.chash)) AND (p_where IS NULL OR c.metadata @> p_where) AND (p_where_path IS NULL OR c.metadata @@ p_where_path::jsonpath) AND (c.chunk_tsv @@ pg_catalog.plainto_tsquery('english', p_text) OR p_text OPERATOR(nexus.<%) c.chunk_text) LIMIT p_cap $$;
REVOKE EXECUTE ON FUNCTION nexus.text_gate_probe_384(text, text[], jsonb, text, int) FROM PUBLIC; GRANT EXECUTE ON FUNCTION nexus.text_gate_probe_384(text, text[], jsonb, text, int) TO nexus_svc; REVOKE EXECUTE ON FUNCTION nexus.text_gate_probe_768(text, text[], jsonb, text, int) FROM PUBLIC; GRANT EXECUTE ON FUNCTION nexus.text_gate_probe_768(text, text[], jsonb, text, int) TO nexus_svc; REVOKE EXECUTE ON FUNCTION nexus.text_gate_probe_1024(text, text[], jsonb, text, int) FROM PUBLIC; GRANT EXECUTE ON FUNCTION nexus.text_gate_probe_1024(text, text[], jsonb, text, int) TO nexus_svc;
-- POST-CONDITION (see THE GUARD in this file's header). Fails the migration, and so rolls this changeset -- back, unless the three probes are SECURITY DEFINER functions owned by the migrating role, the owner policy -- names exactly that role, and no role the precondition guards against (nexus_svc, or any other login role -- that is subject to RLS and has the migrating role's privileges) exists, re-checked here so a drifted -- precondition cannot ship the widening. DO $post$ DECLARE me oid := (SELECT r.oid FROM pg_catalog.pg_roles r WHERE r.rolname = current_user); n_probes int; bad_probes text; pol_roles oid[]; exposed_roles text; BEGIN SELECT count(*), string_agg(p.proname, ', ') FILTER (WHERE p.proowner <> me OR NOT p.prosecdef) INTO n_probes, bad_probes FROM pg_catalog.pg_proc p WHERE p.pronamespace = 'nexus'::regnamespace AND p.proname IN ('text_gate_probe_384', 'text_gate_probe_768', 'text_gate_probe_1024'); IF n_probes <> 3 THEN RAISE EXCEPTION 'vectors-029: expected 3 text_gate_probe functions, found %', n_probes; END IF; IF bad_probes IS NOT NULL THEN RAISE EXCEPTION 'vectors-029: probe(s) % are not SECURITY DEFINER owned by the migrating role %', bad_probes, current_user; END IF; SELECT pol.polroles INTO pol_roles FROM pg_catalog.pg_policy pol WHERE pol.polrelid = 'nexus.chunks'::regclass AND pol.polname = 'chunks_gate_probe_owner_read'; IF pol_roles IS DISTINCT FROM ARRAY[me] THEN RAISE EXCEPTION 'vectors-029: policy chunks_gate_probe_owner_read must name exactly the migrating role % and nothing else, found %', current_user, pol_roles; END IF; SELECT string_agg(r.rolname, ', ' ORDER BY r.rolname) INTO exposed_roles FROM pg_catalog.pg_roles r WHERE (r.rolname = 'nexus_svc' AND (r.rolname = current_user OR pg_catalog.pg_has_role(r.oid, current_user, 'USAGE'))) OR (r.rolname <> current_user AND pg_catalog.pg_has_role(r.oid, current_user, 'USAGE') AND NOT r.rolsuper AND NOT r.rolbypassrls AND r.rolcanlogin); IF exposed_roles IS NOT NULL THEN RAISE EXCEPTION 'vectors-029: role(s) % have the privileges of the migrating role %; the owner policy would apply to them and let them read every tenant''s chunks', exposed_roles, current_user; END IF; END $post$;

