REVOKE EXECUTE ON FUNCTION nexus.text_gate_probe_384(text, text[], jsonb, text, int) FROM nexus_svc; REVOKE EXECUTE ON FUNCTION nexus.text_gate_probe_768(text, text[], jsonb, text, int) FROM nexus_svc; REVOKE EXECUTE ON FUNCTION nexus.text_gate_probe_1024(text, text[], jsonb, text, int) FROM nexus_svc; GRANT EXECUTE ON FUNCTION nexus.text_gate_probe_384(text, text[], jsonb, text, int) TO PUBLIC; GRANT EXECUTE ON FUNCTION nexus.text_gate_probe_768(text, text[], jsonb, text, int) TO PUBLIC; GRANT EXECUTE ON FUNCTION nexus.text_gate_probe_1024(text, text[], jsonb, text, int) TO PUBLIC; DROP POLICY IF EXISTS chunks_gate_probe_owner_read ON nexus.chunks;
